import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Adds the claim (date blank: the sheet's entry date, else its today), due by its date plus the terms in force on that date for its person (their own, else their grade's on that date, else the sheet's) and moved past the sheet's holidays, fixed from now on; a late entry when that due-by is in a soft-closed period. */
public class BuildClaim {
    public void build(@Val Person person, @Val ClaimInput input, ClaimRepository repository,
            SheetRepository sheets, SettingRepository settings, PeriodRepository periods, HolidayRepository holidays, Out<Claim> claim) {
        LocalDate date = input.date() != null ? input.date()
                : settings.entryDate(person.getSheetId(), sheets.today(person.getSheetId()));
        LocalDate dueBy = dueBy(person, date, settings, holidays);
        Claim added = repository.insert(person.getSheetId(), person.getId(), input.amount(), date, input.note(),
                input.corrects(), dueBy);
        if (periods.softClosedOn(person.getSheetId(), dueBy)) {
            repository.markLate(added);
        }
        claim.set(added);
    }

    /**
     * The due-by a claim of the person dated {@code date} is fixed with: its date plus the terms in force then for them,
     * moved past the sheet's holidays (as they stand now) to the next day that is not one.
     */
    static LocalDate dueBy(Person person, LocalDate date, SettingRepository settings, HolidayRepository holidays) {
        return holidays.nextWorkingDay(person.getSheetId(),
                date.plusDays(settings.dated(person.getSheetId()).terms(person, date)));
    }
}
